-- NBA GM 2026-27 option-inclusive contract provenance -- UNVERIFIED STAGING ONLY.
-- An additive, private audit ledger; no game economics or run state reads it.
-- Do not use candidate salaries in live catalog or v2/v3 economies.
-- 330 candidate prices are NOT 330 source-verified real NBA contracts.
create table if not exists private.nba_gm_contract_candidates_2026_27 (
  player_id text primary key references private.nba_gm_dev_players(id),
  player_name text not null,
  game_team_code text not null,
  prior_salary bigint not null check (prior_salary > 0),
  prior_contract text not null check (prior_contract in ('1YR','3YR')),
  candidate_salary bigint not null check (candidate_salary > 0),
  actual_end_season text,
  candidate_contract text check (candidate_contract in ('1YR','3YR')),
  option_notes text not null default '',
  source_url text not null,
  source_player_id text not null default '',
  verification_status text not null,
  source_issue text not null default '',
  independently_verified boolean not null default false,
  snapshot_date date not null default date '2026-11-01',
  constraint nba_gm_candidate_term_has_expiration
    check (candidate_contract is null or actual_end_season is not null)
);
revoke all on private.nba_gm_contract_candidates_2026_27 from public, anon, authenticated;
alter table private.nba_gm_contract_candidates_2026_27 enable row level security;
comment on table private.nba_gm_contract_candidates_2026_27 is
  'Private unverified research candidates. Never active in NBA GM player pricing or saved franchise economies.';
insert into private.nba_gm_contract_candidates_2026_27
(player_id,player_name,game_team_code,prior_salary,prior_contract,
 candidate_salary,actual_end_season,candidate_contract,option_notes,source_url,
 source_player_id,verification_status,source_issue,independently_verified)
values
