on conflict (player_id) do update set
 candidate_salary=excluded.candidate_salary,
 actual_end_season=excluded.actual_end_season,
 candidate_contract=excluded.candidate_contract,
 option_notes=excluded.option_notes,
 source_url=excluded.source_url,
 source_player_id=excluded.source_player_id,
 verification_status=excluded.verification_status,
 source_issue=excluded.source_issue,
 independently_verified=excluded.independently_verified;
do $check$
declare v_total integer; v_verified integer;
begin
 select count(*), count(*) filter (where independently_verified)
 into v_total,v_verified from private.nba_gm_contract_candidates_2026_27;
 if v_total <> 330 or v_verified <> 0 then
   raise exception 'NBA GM research staging census mismatch (total=%, certified=%)',v_total,v_verified;
 end if;
 if exists (select 1 from private.nba_gm_contract_candidates_2026_27
   where candidate_contract is null and actual_end_season is not null) then
   raise exception 'NBA GM contract term not classified despite recorded expiry';
 end if;
end
$check$;
